"""krun job: the pre-registered bar test for C-prime.

Fable5's bar, declared before the run and not moved afterwards: on 100K at
production chunk granularity (s200), with the candidate band widened to the
depth the miss-rank diagnostic says the evidence actually lives at (k=1000,
p95 was 465 at this tier) and the cross-encoder rescoring that band,

    cover@4000 >= 0.70   C-prime passes, widening plus CE is the fix
    cover@4000 <  0.60   C-prime is insufficient, the structural route starts
    in between           grey, decided by the k=2000 rerun

The earlier CE measurement does not settle this: it ran at w1 chunking and
k=50, which is neither the granularity production uses nor deep enough to put
the missed evidence in front of the CE at all.

Package and scripts are embedded rather than cloned, so this measures the exact
local tree (local HEAD carries commits the remote does not have).
"""
import base64, json, os, subprocess, sys, time

WORK = '/kaggle/working'
REPO = WORK + '/mnemonics'
RESULTS = WORK + '/results'
CE_MODEL = 'BAAI/bge-reranker-v2-m3'
os.makedirs(RESULTS, exist_ok=True)

PKG_B64 = ""
FILES_B64 = {"beam_probe.py": "", "beam_cover_diversity.py": ""}


def retry(fn, what, tries=3, wait=8):
    for i in range(1, tries + 1):
        try:
            return fn()
        except Exception as e:
            print('[retry %d/%d] %s: %s' % (i, tries, what, e), flush=True)
            if i < tries:
                time.sleep(wait * i)
            else:
                raise


def clone():
    subprocess.run(['rm', '-rf', REPO], check=False)
    subprocess.run(['git', 'clone', '--depth', '1',
                    'https://github.com/nakata-app/mnemonics.git', REPO], check=True)


retry(clone, 'git clone')
retry(lambda: subprocess.run(
    [sys.executable, '-m', 'pip', 'install', '-q', '-e', REPO,
     'sentence-transformers', 'numpy', 'pyarrow', 'huggingface_hub'], check=True),
    'pip install')

with open(WORK + '/pkg.tgz', 'wb') as f:
    f.write(base64.b64decode(PKG_B64))
subprocess.run(['rm', '-rf', REPO + '/mnemonics'], check=True)
subprocess.run(['tar', 'xzf', WORK + '/pkg.tgz', '-C', REPO], check=True)
for name, b64 in FILES_B64.items():
    with open(REPO + '/benchmarks/' + name, 'wb') as f:
        f.write(base64.b64decode(b64))
print('package + scripts written from embedded tree', flush=True)

import torch
print('cuda:', torch.cuda.is_available(), flush=True)

env = os.environ.copy()
env['PYTHONUNBUFFERED'] = '1'
env['MNEMONICS_RERANK_MODEL'] = CE_MODEL
env['MNEMONICS_DETERMINISTIC'] = '1'
env['MNEMONICS_RERANK_MAX_LENGTH'] = '512'
env['MNEMONICS_RERANK_BATCH_SIZE'] = '16'
env['PYTORCH_ALLOC_CONF'] = 'expandable_segments:True'


def stage(k, limit, tag):
    out = RESULTS + '/' + tag
    cmd = [sys.executable, '-u', 'benchmarks/beam_cover_diversity.py',
           '--sizes', '100K', '--windows', 's200', '--arms', 'baseline',
           '--candidate-k', str(k), '--rerank', '--out-dir', out]
    if limit:
        cmd += ['--limit', str(limit)]
    print('\n=== %s k=%d limit=%s ===' % (tag, k, limit or 'all'), flush=True)
    r = subprocess.run(cmd, cwd=REPO, env=env)
    print('%s returncode=%d' % (tag, r.returncode), flush=True)
    return r.returncode == 0


# Smoke on 2 conversations first: a broken CE path should not cost the session.
if not stage(1000, 2, 'smoke_k1000'):
    print('SMOKE FAILED', flush=True)
    sys.exit(1)
print('SMOKE OK', flush=True)

ok = {}
ok['k1000'] = stage(1000, 0, 'bar_k1000')
# k=2000 is the tie-breaker the bar calls for; run it while the session is warm.
try:
    ok['k2000'] = stage(2000, 0, 'bar_k2000')
except Exception as e:
    print('[k2000 failed] %s' % e, flush=True)
    ok['k2000'] = False

json.dump({'ce_model': CE_MODEL, 'stages': ok},
          open(RESULTS + '/bar_summary.json', 'w'), indent=2)
print('\n=== BITTI ===', json.dumps(ok), flush=True)
